var n=`1254-trinidad-chicken-curry`;var t=`world-1254`;var r=`TT`;var a=`central-america-caribbean`;var o=4;var s=118;var g={en:`Trinidad Chicken Curry`,ua:`Куряче карі по-тринідадськи`};var d={en:`Trinidad Chicken Curry is a dish from Trinidad and Tobago featuring chicken thigh, garlic, yellow onion, tomato. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Куряче карі по-тринідадськи, страва кухні країни Тринідад і Тобаго з такими основними складниками: куряче стегно, часник, жовта цибуля, помідор. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var c=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 65 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 65 хвилин.`,t:[`marinating`],m:65,i:[[`chicken-thigh`,850,`g`],[`curry-powder`,30,`g`],[`ground-cumin`,5,`g`],[`garlic`,4,`clove`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`tomato`,240,`g`],[`canola-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 38 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 38 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:38,i:[[`potato`,350,`g`],[`water`,650,`ml`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var h={slug:n,id:t,country:`TT`,region:a,servings:4,minutes:118,title:g,text:d,steps:c};export{r as country,h as default,t as id,s as minutes,a as region,o as servings,n as slug,c as steps,d as text,g as title};